+<head>
+  <meta charset="utf-8">
+  <meta name="viewport" content="width=device-width, initial-scale=1">
+  <title>Index</title>
+</head>
+<body>
+  <main><h1>Pages</h1><ul>${items}</ul></main>
+</body>
+</html>
+`;
+}
